rulesets.pack-1:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_size_ascii/{doc} {
      allow get: if 'abc'.size() == 3;
    }
    match /c_size_emoji_1/{doc} {
      allow get: if '😀'.size() == 1;
    }
    match /c_size_emoji_2/{doc} {
      allow get: if '😀'.size() == 2;
    }
    match /c_size_combining/{doc} {
      allow get: if 'é'.size() == 2;
    }
    match /c_size_empty/{doc} {
      allow get: if ''.size() == 0;
    }
    match /c_utf8_size_emoji/{doc} {
      allow get: if '😀'.toUtf8().size() == 4;
    }
    match /c_matches_full/{doc} {
      allow get: if 'abc'.matches('a.c');
    }
    match /c_matches_partial_is_false/{doc} {
      allow get: if 'abc'.matches('b');
    }
    match /c_matches_dotstar/{doc} {
      allow get: if 'abc'.matches('.*b.*');
    }
    match /c_matches_digit_two_backslashes/{doc} {
      allow get: if '123'.matches('\\d+');
    }
    match /c_matches_dot_emoji/{doc} {
      allow get: if '😀'.matches('.');
    }
    match /c_matches_dot_newline/{doc} {
      allow get: if 'a\nb'.matches('a.b');
    }
    match /c_matches_dotall_flag/{doc} {
      allow get: if 'a\nb'.matches('(?s)a.b');
    }
    match /c_matches_counted/{doc} {
      allow get: if 'aaa'.matches('a{3}');
    }
    match /c_matches_on_int/{doc} {
      allow get: if (1).matches('1');
    }
    match /c_split_simple/{doc} {
      allow get: if 'a,b,c'.split(',') == ['a', 'b', 'c'];
    }
    match /c_split_regex/{doc} {
      allow get: if 'a1b22c'.split('[0-9]+') == ['a', 'b', 'c'];
    }
    match /c_split_dot_is_regex/{doc} {
      allow get: if 'a.b'.split('.') == ['', '', ''];
    }
    match /c_split_trailing_empty_kept/{doc} {
      allow get: if 'a,b,'.split(',') == ['a', 'b', ''];
    }
    match /c_split_trailing_empty_dropped/{doc} {
      allow get: if 'a,b,'.split(',') == ['a', 'b'];
    }
    match /c_split_leading_empty/{doc} {
      allow get: if ',a'.split(',') == ['', 'a'];
    }
    match /c_split_empty_string/{doc} {
      allow get: if ''.split(',') == [''];
    }
    match /c_split_empty_string_size/{doc} {
      allow get: if ''.split(',').size() == 1;
    }
    match /c_split_empty_sep/{doc} {
      allow get: if 'abc'.split('') == ['a', 'b', 'c'];
    }
    match /c_split_path_style/{doc} {
      allow get: if '/a/b'.split('/') == ['', 'a', 'b'];
    }
    match /c_replace_all/{doc} {
      allow get: if 'aaa'.replace('a', 'b') == 'bbb';
    }
    match /c_replace_regex/{doc} {
      allow get: if 'a.b'.replace('.', '-') == '---';
    }
    match /c_replace_group_dollar/{doc} {
      allow get: if 'ab'.replace('(a)(b)', '$2$1') == 'ba';
    }
    match /c_replace_group_backslash/{doc} {
      allow get: if 'ab'.replace('(a)(b)', '\\2\\1') == 'ba';
    }
    match /c_replace_literal_dollar/{doc} {
      allow get: if 'ab'.replace('(a)(b)', '$2$1') == '$2$1';
    }
    match /c_replace_empty_pattern/{doc} {
      allow get: if 'ab'.replace('', '-') == '-a-b-';
    }
    match /c_lower_e_acute/{doc} {
      allow get: if 'É'.lower() == 'é';
    }
    match /c_upper_sharp_s/{doc} {
      allow get: if 'ß'.upper() == 'SS';
    }
    match /c_upper_sharp_s_unchanged/{doc} {
      allow get: if 'ß'.upper() == 'ß';
    }
    match /c_lower_dotted_i/{doc} {
      allow get: if 'İ'.lower().size() == 2;
    }
    match /c_lower_final_sigma/{doc} {
      allow get: if 'ΟΣ'.lower() == 'ος';
    }
    match /c_trim_tab_newline/{doc} {
      allow get: if '\ta\n'.trim() == 'a';
    }
    match /c_trim_nbsp/{doc} {
      allow get: if '\u00a0a'.trim() == 'a';
    }
    match /c_index/{doc} {
      allow get: if 'abc'[1] == 'b';
    }
    match /c_index_out_of_range/{doc} {
      allow get: if 'abc'[5] == 'x';
    }
    match /c_index_emoji/{doc} {
      allow get: if '😀a'[1] == 'a';
    }
    match /c_range/{doc} {
      allow get: if 'abcdef'[1:3] == 'bc';
    }
    match /c_range_past_end/{doc} {
      allow get: if 'abc'[1:10] == 'bc';
    }
    match /c_range_reversed/{doc} {
      allow get: if 'abc'[2:1] == '';
    }
    match /c_concat/{doc} {
      allow get: if 'a' + 'b' == 'ab';
    }
    match /c_compare_unicode/{doc} {
      allow get: if 'é' > 'z';
    }
    match /c_compare_emoji_vs_bmp/{doc} {
      allow get: if '😀' > '\uffff';
    }
    match /c_string_of_int/{doc} {
      allow get: if string(1) == '1';
    }
    match /c_string_of_float/{doc} {
      allow get: if string(1.5) == '1.5';
    }
    match /c_string_of_whole_float/{doc} {
      allow get: if string(1.0) == '1.0';
    }
    match /c_string_of_whole_float_short/{doc} {
      allow get: if string(1.0) == '1';
    }
    match /c_string_of_bool/{doc} {
      allow get: if string(true) == 'true';
    }
    match /c_string_of_null/{doc} {
      allow get: if string(null) == 'null';
    }
    match /c_string_of_list/{doc} {
      allow get: if string([1, 'a']) == '[1, a]';
    }
  }
}

rulesets.pack-2:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_string_of_list_any/{doc} {
      allow get: if string([1, 'a']) is string;
    }
    match /c_string_of_large_float_any/{doc} {
      allow get: if string(10000000000000000000000.0) is string;
    }
    match /c_int_of_string/{doc} {
      allow get: if int('12') == 12;
    }
    match /c_int_of_float_string/{doc} {
      allow get: if int('1.5') == 1;
    }
    match /c_int_of_spaced_string/{doc} {
      allow get: if int(' 12') == 12;
    }
    match /c_float_of_string/{doc} {
      allow get: if float('1.5') == 1.5;
    }
    match /c_float_of_exp_string/{doc} {
      allow get: if float('1e3') == 1000.0;
    }
    match /c_to_utf8/{doc} {
      allow get: if 'abc'.toUtf8() == b'abc';
    }
    match /c_escape_unicode/{doc} {
      allow get: if '\u00e9' == 'é';
    }
    match /c_escape_quote/{doc} {
      allow get: if 'a\'b'.size() == 3;
    }
    match /c_double_quotes/{doc} {
      allow get: if "dq" == 'dq';
    }
    match /c_escape_hex/{doc} {
      allow get: if '\x41' == 'A';
    }
    match /c_in_string/{doc} {
      allow get: if 'b' in 'abc';
    }
  }
}

